function Page_ActAdvanceNoticeViewBase.CreatePageActView(configId,parentPref)
    ---@type act_advance_notice_config_cell
    local config = CommonHelper:GetTableDataByID(ConfigNames.act_advance_notice_config, configId)
    local pageView
    if config==nil  then
        logError("该活动id没有对应的pageView",configId)
    elseif config.C_ID == RaceActId.RaceTrot then
        pageView = Page_ActAdvanceNoticeRaceTrotView()
    elseif config.C_ID == RaceActId.RaceTop then
        pageView = Page_ActAdvanceNoticeRaceTopView()
    elseif config.C_ID == RaceActId.RaceGVG then
        pageView = Page_ActAdvanceNoticeRaceGVGView()
    elseif config.C_ID ==RaceActId.RaceSuperBattle then
        pageView = Page_ActAdvanceNoticeRaceSuperBattleView()
    end
    if pageView then
        Page_ActAdvanceNoticeViewBase.initialize(pageView, config, parentPref)
        pageView:OnAwake()
    end
    return pageView
end

function Page_ActAdvanceNoticeViewBase:initialize(config,parentPref)
    if self and config and parentPref  then
        self.parentPref=parentPref
        ---@type act_advance_notice_config_cell
        self.config = config
        self.canvasGroup = UIUtil.GetTypeChildWightByParent(self:GetPageName(), self.parentPref, typeof(CanvasGroup))
        self.gameObject = self.canvasGroup.gameObject
        self:SetCanvasGroup(false)
        self.IsOpen=false
    else
        logWarn("该继承未初始化基类")
    end
end

function Page_ActAdvanceNoticeViewBase:Open()
    CommonHelper:GetComponentSetUITexture("pagebg", self.parentPref, self.config.actbg .. ".png", self:GetUIModuleID())
    self:SetCanvasGroup(true)
    self.IsOpen=true
    self:OnOpen()
end

function Page_ActAdvanceNoticeViewBase:Close()
    self.IsOpen=false
    self:SetCanvasGroup(false)
    self:OnClose()
end

function Page_ActAdvanceNoticeViewBase:SetCanvasGroup(active)
    UIUtil.ShowCanvasGroup(self.canvasGroup,active)
end

