function Page_ActAdvanceNoticeViewBase:GetDataTimeString(tempstr)
    local _beginTime, _endTime = ActAdvanceNoticeDataManager:Get():GetActTime(self.config.C_ID)
    --local bTime, eTime = ActAdvanceNoticeDataManager:Get():GetActTime(self.config.C_ID)
    --local _beginTime = CommonHelper:ConvertIntToDataTime(bTime * 1000)
    --local _endTime = CommonHelper:ConvertIntToDataTime(eTime * 1000)

    local tempstr=tempstr and tempstr or TemplateStringID.ActAdvanceNoticeTimeText
    local bHour =  _beginTime.Hour>9 and _beginTime.Hour or string.format("0%s",_beginTime.Hour)
    local eHour =  _endTime.Hour>9 and _endTime.Hour or string.format("0%s",_endTime.Hour)
    local bMinute =  _beginTime.Minute>9 and _beginTime.Minute or string.format("0%s",_beginTime.Minute)
    local eMinute =  _endTime.Minute>9 and _endTime.Minute or string.format("0%s",_endTime.Minute)
    local durationTime = string.format(CommonHelper:GetTempStr_Default(tempstr,
            _beginTime.Month, _beginTime.Day, bHour, bMinute,
            _endTime.Month, _endTime.Day, eHour, eMinute))
    return durationTime
end

